cd /root && python3 - <<'EOF'
import json,os,re,urllib.request
env={}
for p in ("/root/.env","/root/Iryna_Karmazina/.env","/root/.n8n_env"):
    if os.path.exists(p):
        for ln in open(p):
            if "=" in ln and not ln.strip().startswith("#"):
                k,v=ln.strip().split("=",1); env.setdefault(k.strip(),v.strip().strip('"\''))
key=env.get("N8N_API_KEY") or env.get("N8N_KEY") or ""
base=env.get("N8N_BASE_URL") or "https://irynakarmazina.app.n8n.cloud"
print("KEY_PRESENT", bool(key), "BASE", base)
def api(p):
    r=urllib.request.Request(base.rstrip("/")+p,headers={"X-N8N-API-KEY":key,"Accept":"application/json"})
    return json.loads(urllib.request.urlopen(r,timeout=60).read().decode())
wfs=api("/api/v1/workflows?limit=100")["data"]
for w in wfs:
    if "aersk" in w["name"]:
        print("WF:",w["id"],w["name"],"active=",w["active"])
        full=api("/api/v1/workflows/"+w["id"])
        for n in full["nodes"]:
            u=(n.get("parameters") or {}).get("url","")
            u=re.sub(r"[A-Za-z0-9_\-]{25,}","<masked>",str(u))
            cr=",".join((n.get("credentials") or {}).keys())
            print("  -",n["name"],"|",n["type"].split(".")[-1],"|",u[:90],"| cred:",cr)
EOF
